            excessBlobGas);

        // below floor
        ulong expectedExcessBlobGas = excessBlobGas + (targetBlobGasPerBlock * (spec.MaxBlobCount - spec.TargetBlobCount) / spec.MaxBlobCount);
        yield return (
            excessBlobGas,
            (int)spec.TargetBlobCount,
            (ulong)baseFeePerGas + 100,
            expectedExcessBlobGas);
    }
}

